command:
$ErrorActionPreference='Stop'; $script=Join-Path $env:TEMP 'display_scale_keyboard_options.py'; @'

import ctypes as c, time
from pywinauto import Desktop
from pywinauto.keyboard import send_keys
import psutil

spec=None
for x in Desktop(backend="uia").windows():
    try:
        if psutil.Process(x.element_info.process_id).name().lower()=="applicationframehost.exe" and x.window_text():
            spec=Desktop(backend="uia").window(handle=x.handle); break
    except Exception: pass
if spec is None:
    c.windll.shell32.ShellExecuteW(None,"open","ms-settings:display",None,None,1)
    end=time.monotonic()+15
    while time.monotonic()<end:
        for x in Desktop(backend="uia").windows():
            try:
                if psutil.Process(x.element_info.process_id).name().lower()=="applicationframehost.exe" and x.window_text():
                    spec=Desktop(backend="uia").window(handle=x.handle); break
            except Exception: pass
        if spec is not None: break
        time.sleep(.25)
if spec is None: raise RuntimeError("Settings host missing")
combo=spec.child_window(auto_id="SystemSettings_Display_Scaling_ItemSizeOverride_ComboBox",control_type="ComboBox").wrapper_object()
for method in ("texts","selected_text","selected_index","item_count"):
    try:
        val=getattr(combo,method)()
        print("COMBO_METHOD",method,repr(val),flush=True)
    except Exception as e:
        print("COMBO_METHOD_ERROR",method,repr(e),flush=True)
combo.set_focus()
time.sleep(.2)
send_keys("%{DOWN}")
time.sleep(.8)
seen=set()
for w in Desktop(backend="uia").windows():
    try:
        for d in w.descendants():
            if d.element_info.control_type!="ListItem": continue
            name=(d.element_info.name or d.window_text() or "").strip()
            if "%" in name and name not in seen:
                seen.add(name)
                r=d.rectangle()
                print("SCALE_OPTION",repr(name),repr(d.element_info.automation_id),r.left,r.top,r.width(),r.height(),flush=True)
    except Exception: pass
send_keys("{ESC}")

'@ | Set-Content -LiteralPath $script -Encoding utf8; python -X utf8 $script; $rc=$LASTEXITCODE; Remove-Item $script -Force -ErrorAction SilentlyContinue; exit $rc
